<script setup lang="ts">
import {ref,watch} from 'vue';import {Link} from '@inertiajs/vue3';import Modal from './Modal.vue';import LoadingState from './LoadingState.vue';import {json,dateLabel} from '../lib/format';
const props=defineProps<{id:string;canAccept:boolean}>();const emit=defineEmits<{close:[]}>();const detail=ref<any>(),error=ref('');
const timezone=Intl.DateTimeFormat().resolvedOptions().timeZone;
const loading=ref(false);let requestNumber=0;
async function load(){const number=++requestNumber;error.value='';loading.value=true;try{const result=await json('/invitations/'+props.id);if(number===requestNumber)detail.value=result;}catch(e:any){if(number===requestNumber)error.value=e.message;}finally{if(number===requestNumber)loading.value=false;}}
watch(()=>props.id,()=>{detail.value=undefined;load();},{immediate:true});
</script>
<template><Modal :open="true" title="Review household invitation" @close="emit('close')"><div class="p-6"><p v-if="error" role="alert" class="text-warning">{{error}} <button class="underline" @click="load">Try again</button></p><LoadingState v-if="!detail" :loading="loading" label="Loading invitation"/><template v-if="detail"><h2 class="text-xl">{{detail.household}}</h2><p class="mt-2 text-muted">Invited by {{detail.inviter}} on {{dateLabel(detail.created_at)}}.</p><p v-if="detail.target_nickname" class="help mt-3">You will link to the existing member profile: {{detail.target_nickname}}.</p><h3 class="mt-5 font-medium">Current members</h3><p v-for="(member,index) in detail.members" :key="index" class="border-b border-line py-3">{{member.nickname}}<span v-if="member.owner" class="badge ml-2">Owner</span></p><p class="mt-5 text-muted">Joining gives you access to all shared household financial records. Your records from any previous household stay there.</p><p v-if="!canAccept" class="mt-3 text-warning">Leave your current household before accepting. Owners must transfer ownership or delete their household first.</p><div class="mt-5 flex justify-end gap-2"><button class="btn" @click="emit('close')">Close</button><Link :href="'/invitations/'+id+'/decline'" method="post" as="button" class="btn" @click="emit('close')">Decline</Link><Link v-if="canAccept" :href="'/invitations/'+id+'/accept'" :data="{timezone}" method="post" as="button" class="btn-primary">Join household</Link><button v-else class="btn-primary" disabled>Join household</button></div></template></div></Modal></template>
